\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}

\title{Class-Size Reduction and Reading Achievement: Evidence from a Randomized Encouragement Design}
\author{M.~Halvorsen and D.~Acquah}
\date{February 2026}

\begin{document}
\maketitle

\begin{abstract}
Reducing class size is among the most expensive interventions in
primary education, yet credible causal evidence remains scarce.
Using a randomized encouragement design in 60 primary schools, we
estimate that reducing class size by eight students raises standardized
reading scores by 2.3 points after one year. The study sample covers
4,800 students, and the program is cost-effective at roughly \$180 per
student per year.
\end{abstract}

\section{Introduction}
Class-size policies are politically popular but fiscally demanding.
Prior quasi-experimental studies report widely varying effects,
partly because school-level confounding is difficult to rule out.

\section{Design}
Sixty schools were randomly assigned to receive additional teaching
allocations that encouraged smaller classes in grades two and three.
Compliance was high but imperfect, so we report encouragement-based
estimates throughout.

\input{chapters/results}

\section{Conclusion}
Smaller classes produced a detectable gain in reading achievement,
though the per-student cost shapes the policy calculus.

\end{document}
